head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.v_arrKey = "";
// 화면 리사이징

scwin.fn_GetPar;
scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top); // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_Btm); // 패널라운드 처리
        window.document.body.scroll = "no";
        const arrPar = new Array();
        /***************************************
        opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
        opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
         ***************************************/
        const parentWin = $c.frame.path("../");
        scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
        if (scwin.fn_GetPar !== undefined) {
            scwin.fn_GetPar(arrPar);
            scwin.v_arrKey = arrPar;
        }
        if (scwin.v_arrKey.length >= 1) {
            await scwin.search();
        } else {
            await $c.win.alert("조회 조건이 없습니다");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_P7.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_ColtrlGrtDtl1_OnLoadError
 * @description dts_ColtrlGrtDtl1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ColtrlGrtDtl1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ColtrlGrtDtl1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_P7.dts_ColtrlGrtDtl1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ColtrlGrtDtl1_OnLoadCompleted
 * @description dts_ColtrlGrtDtl1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ColtrlGrtDtl1_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_ColtrlGrtDtl1.errorMsg) {
            await $c.win.alert(dts_ColtrlGrtDtl1.errorMsg);
        }

        // 담보및지급상세 하단 조회
        await scwin.contgntDebtDtl2();

        // 멀티Row의 데이터를 하나로 합치자.
        scwin.appendContents(dts_ColtrlGrtDtl1, pan_Ctnt);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_P7.dts_ColtrlGrtDtl1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ColtrlGrtDtl2_OnLoadError
 * @description dts_ColtrlGrtDtl2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ColtrlGrtDtl2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ColtrlGrtDtl2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_P7.dts_ColtrlGrtDtl2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ColtrlGrtDtl2_OnLoadCompleted
 * @description dts_ColtrlGrtDtl2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ColtrlGrtDtl2_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_ColtrlGrtDtl2.errorMsg) {
            await $c.win.alert(dts_ColtrlGrtDtl2.errorMsg);
        }

        // 멀티Row의 데이터를 하나로 합치자.
        scwin.appendContents(dts_ColtrlGrtDtl2, pan_Ctnt1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_P7.dts_ColtrlGrtDtl2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        // 닫기 버튼 클릭
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00300_P7.img_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name contgntDebtDtl1
 * @description contgnt Debt Dtl1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.contgntDebtDtl1 = async function() {
    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_ColtrlGrtDtl1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ColtrlGrtDtl1=body.content",
        isProcessMsg : false
