/**
 * @method
 * @name contgntDebtDtl2
 * @description contgnt Debt Dtl2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.contgntDebtDtl2 = async function() {
    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_ColtrlGrtDtl2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ColtrlGrtDtl2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
// 조회조건이 담길 배열

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_ColtrlGrtDtl1.removeAll();
    dts_ColtrlGrtDtl2.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    return true;
};

/**
 * @method
 * @name search
 * @description 담보및지급보증 상세 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // 상단 조회
    await scwin.contgntDebtDtl1();
};

/**
 * @method
 * @name appendContents
 * @description 컨텐츠 append
 * @param {*} pDs pDs
 * @param {*} pPanel pPanel
 * @returns {void}
 * @hidden N
 */
scwin.appendContents = function(pDs, pPanel) {
    let strContent = "<div style='overflow-x:auto;overflow-y:scroll;width:100%;height:350px;font-family:돋움체;'>";
    for (let nRow = 1; nRow <= pDs.getRowCount(); nRow++) {
        strContent = strContent + pDs.getCellData(nRow, "CTNT") + "";
    }
    strContent = strContent + "</div>";
    pPanel.innerHTML = strContent;
};
